    },
    {
      "card_ids": ["C14"],
      "claim": "GSK1322322, a structurally distinct but highly transferable molecule, showed 57% absolute oral bioavailability in the fasted state in healthy volunteers, directly matching the fasted condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "LSD, a basic amine-containing drug with high transferability, showed 80% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tramadol, a basic amine-containing analgesic with high transferability, showed 68% mean oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues with high transfer scores show absolute oral bioavailability well above the 20% threshold, ranging from about 46% to 98%, including a fasted-state measurement of 57%. The query's morphinan scaffold is consistent with these high-bioavailability compounds, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "Only one retrieved record explicitly reports a fasted-state condition; other records are not explicitly fasted, though the fasted record also supports high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

